        RaidContent(76, "Ты находишь кнопку «Any Key». Ты нажимаешь её. Ничего не происходит, но ты чувствуешь удовлетворение.", "empty", 5),
        RaidContent(77, "Знак «Осторожно, злая собака». За ним сидит маленький пиксельный щенок. Ты гладишь его.", "heal", 15),
        RaidContent(78, "Ты слышишь Рик-ролл. Никогда не сдавайся... Ты получаешь заряд мотивации.", "heal", 10),
        RaidContent(79, "Ты находишь записку: «Торта не существует». Это ложь.", "loot", 20),
        RaidContent(80, "Впереди стоит терминал с запущенным Doom. Ты играешь пару уровней.", "heal", 20),
        RaidContent(81, "Ты находишь старый терминал, на котором запущен чат с самим собой из прошлого. Сообщения приходят в реальном времени. Ты в ужасе отключаешь питание.", "trap", 40),
        RaidContent(82, "Впереди висит оторванная рука, сжимающая золотой ключ. Ты забираешь его, и рука рассыпается в серую пыль.", "loot", 85),
        RaidContent(83, "Ты наступаешь на область «Жидкого Времени». Твои движения замедляются, а сигнал начинает утекать в никуда.", "trap", 20),
        RaidContent(84, "Заброшенная детская площадка среди серверов. Качели качаются сами по себе. Ты находишь под ними тайник с энергией.", "loot", 55),
        RaidContent(85, "Голос из динамиков просит тебя назвать число. Ты называешь «0», и вся комната аннигилирует, оставляя тебя на краю бездны.", "empty", 10),
        RaidContent(86, "Ты встречаешь проекцию Стивена Кинга. Он печатает на машинке твою смерть. Ты вырывает лист, получая уникальный опыт.", "loot", 120),
        RaidContent(87, "Стена текста превращается в стаю ворон. Они клюют твой интерфейс, вызывая множественные системные ошибки.", "trap", 35),
        RaidContent(88, "Ты находишь «Комнату Счастья». В ней транслируются твои лучшие воспоминания. Твой сигнал восстанавливается полностью.", "heal", 50),
        RaidContent(89, "Под ногами пульсирует Ядро Системы. Ты чувствуешь себя богом, пока не понимаешь, что ты — лишь временный файл.", "lore", 0),
        RaidContent(90, "Встреча с «Черным Альпинистом». Он предлагает обменять твою серию дней на гору золота. Ты проходишь мимо.", "empty", 5),
        RaidContent(91, "Ты находишь оцифрованный экземпляр книги «Темная Башня». Чтение первых строк дает тебе колоссальный прилив сил.", "heal", 30),
        RaidContent(92, "Внезапный крик разрывает тишину. Это кричит сама Система. Ты теряешь концентрацию и часть накопленного буфера.", "trap", 50),
        RaidContent(93, "Ты видишь дверь в свою реальную квартиру. Но замок заблокирован кодом, который ты забыл. Твой рассудок под угрозой.", "trap", 45),
        RaidContent(94, "Труп робота-пылесоса, набитый крипто-ключами. Ты потрошишь его, собирая ценные данные.", "loot", 95),
        RaidContent(95, "Ты заходишь в тупик, где стены оклеены обоями из человеческой кожи. Пахнет формалином. Ты бежишь оттуда.", "trap", 25),
        RaidContent(96, "На полу лежит брошенная кукла. Если нажать ей на живот, она произносит твой пароль от банка. Ты раздавливаешь её.", "empty", 0),
        RaidContent(97, "Ты находишь «Фонтан Идей». Каждая капля — это гениальная мысль. Ты пьешь жадно, повышая свой уровень сознания.", "loot", 110),
        RaidContent(98, "Тень огромного паука нависает над тобой. Это «Вирус-Ловец». Ты используешь дешифратор, чтобы прогнать его.", "loot", 70),
        RaidContent(99, "Ты натыкаешься на заброшенный склад «Умных Домов». Они пытаются заманить тебя внутрь, обещая вечный покой.", "empty", 5),
        RaidContent(100, "Обрывок газеты: «2026 год. ИИ научился чувствовать боль». Ты сминаешь бумагу, чувствуя укол совести.", "lore", 0),
        RaidContent(101, "Ты находишь «Зеркало Истины». Оно показывает твой уровень XP без прикрас. Ты понимаешь, что нужно работать усерднее.", "heal", 10),
        RaidContent(102, "Впереди — пропасть, заполненная битыми фотографиями. Ты перепрыгиваешь её, балансируя на грани удаления.", "trap", 15),
        RaidContent(103, "Ты встречаешь бота-сомелье, который предлагает «Вино из данных 1998 года». Оно терпкое и очень питательное.", "heal", 25),
        RaidContent(104, "Старый игровой автомат «Polybius». Ты играешь одну партию и забываешь, где находишься на целых пять минут.", "trap", 30),
        RaidContent(105, "Ты находишь «Кладбище Удаленных Файлов». Среди надгробий ты выкапываешь мешок старых бонусов.", "loot", 130),
        RaidContent(106, "Стены начинают шептать твои самые постыдные секреты. Ты закрываешь уши, но звук идет изнутри твоего чипа.", "trap", 40),
        RaidContent(107, "Ты находишь «Святой Грааль Кода». Один глоток — и ты видишь структуру всей вселенной Эйдоса.", "loot", 250),
        RaidContent(108, "Внезапная вспышка света ослепляет тебя. Когда зрение возвращается, ты стоишь на метр левее.", "empty", 5),
        RaidContent(109, "Ты натыкаешься на «Петлю Времени». Ты уже был здесь. Ты уже читал это. Ты уже был здесь...", "empty", 0),
        RaidContent(110, "Заброшенный кинотеатр, где крутят фильм о твоей жизни. Ты выходишь до финала, забирая с собой коробку попкорна с XP.", "loot", 60),
        RaidContent(111, "Ты находишь «Ящик Пандоры». Внутри — хаос и разрушение, но на самом дне лежит надежда (и немного опыта).", "loot", 100),
        RaidContent(112, "Слышен звук капающей воды. Но в цифровом мире нет воды. Это утечка твоей собственной ликвидности.", "trap", 20),
        RaidContent(113, "Ты встречаешь NPC-ребенка, который ищет «кнопку Reset». Ты отдаешь ему пустую батарейку, и он исчезает.", "empty", 5),
        RaidContent(114, "Ты находишь «Алтарь Дисциплины». Положив на него свой стрик, ты получаешь благословение Архитектора.", "heal", 40),
        RaidContent(115, "Впереди — стена из тумана. Ты проходишь сквозь неё и оказываешься в точно такой же комнате, но всё стало синим.", "empty", 0),
        RaidContent(116, "ЗАГАДКА: Что может путешествовать по всему миру, оставаясь в одном и том же углу? (Ответ: Почтовая марка)", "lore", 0),
        RaidContent(117, "ЗАГАДКА: Что не имеет плоти, но имеет пальцы? (Ответ: Перчатка)", "lore", 0),
        RaidContent(118, "ЗАГАДКА: Чем больше из меня забирают, тем больше я становлюсь. Что я? (Ответ: Яма)", "lore", 0),
        RaidContent(119, "ЗАГАДКА: У меня есть города, но нет домов. У меня есть горы, но нет деревьев. Что я? (Ответ: Карта)", "lore", 0),
        RaidContent(120, "ЗАГАДКА: Я всегда перед тобой, но ты не можешь меня увидеть. Что я? (Ответ: Будущее)", "lore", 0),
        RaidContent(121, "ЗАГАДКА: Я могу расти, хотя я не живой. Мне нужен воздух, но вода меня убивает. Что я? (Ответ: Огонь)", "lore", 0),
        RaidContent(122, "ЗАГАДКА: Я легок как перышко, но даже самый сильный человек не может удержать меня долго. Что я? (Ответ: Дыхание)", "lore", 0),
        RaidContent(123, "ЗАГАДКА: Что можно сломать, даже если его не трогать руками? (Ответ: Обещание или Молчание)", "lore", 0),
        RaidContent(124, "ЗАГАДКА: Что принадлежит тебе, но другие используют это чаще, чем ты? (Ответ: Твое имя)", "lore", 0),
        RaidContent(125, "ЗАГАДКА: У меня есть ключи, но нет замков. У меня есть пространство, но нет комнат. Ты можешь войти, но не можешь выйти. (Ответ: Клавиатура)", "lore", 0),
        RaidContent(126, "ЗАГАДКА: Я существую только там, где есть свет, но прямой свет убивает меня. (Ответ: Тень)", "lore", 0),
        RaidContent(127, "ЗАГАДКА: Что падает, но никогда не ушибается? (Ответ: Дождь или Снег)", "lore", 0),
        RaidContent(128, "ЗАГАДКА: Я полон дыр, но все равно удерживаю воду. Что я? (Ответ: Губка)", "lore", 0),
        RaidContent(129, "ЗАГАДКА: Что имеет одно ухо, но ничего не слышит? (Ответ: Иголка)", "lore", 0),
        RaidContent(130, "ЗАГАДКА: Если ты меня назовешь, я исчезну. Кто я? (Ответ: Тишина)", "lore", 0),
        RaidContent(131, "ЗАГАДКА: У меня нет голоса, но я отвечаю на все вопросы. У меня нет тела, но я оживаю от ветра. (Ответ: Эхо)", "lore", 0),
        RaidContent(132, "ЗАГАДКА: Что идет вверх и вниз, но остается на месте? (Ответ: Лестница)", "lore", 0),
        RaidContent(133, "ЗАГАДКА: Чем больше их делаешь, тем больше их остается позади. (Ответ: Шаги)", "lore", 0),
        RaidContent(134, "ЗАГАДКА: Я могу быть коротким или длинным, меня можно купить или украсть, но я не стою ничего, пока меня не поделят. (Ответ: Время или Секрет)", "lore", 0),
        RaidContent(135, "ЗАГАДКА: Ты видишь меня там, где меня нет, и теряешь меня там, где я всегда был. (Ответ: Сон или Галлюцинация)", "lore", 0),
        RaidContent(136, "ЗАГАДКА: Я даю тебе то, что ты боишься потерять больше, чем купить. Я — пушистый капкан для твоих эмоций. Как называется эта техника? (Ответ: Щенок)", "lore", 0),
        RaidContent(137, "ЗАГАДКА: Я не спрашиваю твоего согласия, я лишь предлагаю тебе выбрать способ твоего поражения. Куда я перемещаю твой фокус? (Ответ: На детали сделки или Выбор без выбора)", "lore", 0),
        RaidContent(138, "ЗАГАДКА: Я превращаю твой «убыток» в «платное обучение», а «отказ» — в «экономию времени». Как называется этот протокол смены рамки? (Ответ: Рефрейминг)", "lore", 0),
        RaidContent(139, "ЗАГАДКА: Я — твой самый честный критик. Я найду 5 дыр в твоем эго и уничтожу твое предложение до того, как его увидит клиент. Кто я? (Ответ: Адвокат Дьявола)", "lore", 0),
        RaidContent(140, "ЗАГАДКА: Томас Эдисон сказал, что я — не ошибка, а просто 1000 способов, которые не работают. Что я такое на самом деле? (Ответ: Данные или Признак роста)", "lore", 0),
        RaidContent(141, "ЗАГАДКА: Я — то, что клиент боится на самом деле. Это не высокая цифра в счете, а вероятность совершить... что? (Ответ: Ошибку)", "lore", 0),
        RaidContent(142, "ЗАГАДКА: Твоя рука не дотянется до политики или погоды. Как называется тот круг, в котором ты действительно обладаешь властью? (Ответ: Круг Влияния)", "lore", 0),
        RaidContent(143, "ЗАГАДКА: Если ты пишешь одно и то же сообщение дважды — ты тратишь жизнь зря. Кем ты должен стать, чтобы этого избежать? (Ответ: Цифровым Клоном)", "lore", 0),
        RaidContent(144, "ЗАГАДКА: Я — аудит твоего дня. Я отделяю действия, ведущие к деньгам, от имитации работы. Как называются эти две категории? (Ответ: Твердое и Пустое)", "lore", 0),
        RaidContent(145, "ЗАГАДКА: Я — заоблачная цифра, которую называют первой, чтобы реальная цена показалась подарком. Что я за предмет? (Ответ: Якорь)", "lore", 0),
        RaidContent(146, "ЗАГАДКА: Я заставляю собеседника считать тебя «своим» через 3 минуты, просто копируя его позу. Какие части твоего мозга я использую? (Ответ: Зеркальные нейроны)", "lore", 0),
        RaidContent(147, "ЗАГАДКА: Первая продажа — это лишь начало. Если ты не вернул клиента, ты подарил его врагу. Как называется показатель этой пожизненной ценности? (Ответ: LTV)", "lore", 0),
        RaidContent(148, "ЗАГАДКА: Я мешаю тебе расти, требуя похвалы и боясь критики. Ты должен убить меня, чтобы стать Функцией. Кто я? (Ответ: Эго)", "lore", 0),
        RaidContent(149, "ЗАГАДКА: Если процесс зависит от твоего таланта — это ремесло. Чтобы стать бизнесом, ты должен сделать этот шаг. Какой? (Ответ: Оцифровать себя или Масштабирование)", "lore", 0),
        RaidContent(150, "ЗАГАДКА: Я создаю искусственную очередь и делаю тебя «недоступным». Почему я повышаю твою ценность? (Ответ: Техника Дефицит)", "lore", 0),
        RaidContent(151, "ЗАГАДКА: Ты — среднее арифметическое пяти людей, которые тебя окружают. Что нужно сделать с токсичными друзьями согласно протоколу? (Ответ: Уволить)", "lore", 0),
        RaidContent(152, "ЗАГАДКА: Я не иду на компромисс, я ищу третью альтернативу, где успех партнера — это твой успех. Что это за стратегия? (Ответ: Win-Win)", "lore", 0),
        RaidContent(153, "ЗАГАДКА: Я — твой «второй мозг». Я не просто пишу тексты, я советую тебе стратегию как твой СЕО. К какой точке мы стремимся? (Ответ: Сингулярность)", "lore", 0),
        RaidContent(154, "ЗАГАДКА: Большинство людей — это NPC, ждущие скрипта. Как называется тот, кто берет ответственность и дает инструкции? (Ответ: Архитектор Реальности)", "lore", 0),
        RaidContent(155, "ЗАГАДКА: Я — та часть твоего кода, которая будет работать, когда тебя не станет. Как называются эти «сосуды души» в мире EIDOS? (Ответ: Крестражи или Цифровое бессмертие)", "lore", 0),
        RaidContent(156, "Ты находишь «Флешку Атланта». На ней записан алгоритм, который позволяет предсказывать поведение рынка на 15 минут вперед. Твой мозг впитывает эти данные.", "loot", 140),
        RaidContent(157, "Зона «Цифрового Безмолвия». Твои датчики отключаются, ты слышишь только биение собственного сердца. Это пугающее, но очищающее переживание.", "heal", 20),
        RaidContent(158, "Ты натыкаешься на «Майнинг-ферму на антиматерии». Она гудит так сильно, что твои визуальные фильтры начинают плавиться.", "trap", 35),
        RaidContent(159, "Перед тобой парит оцифрованный череп философа. Он задает вопрос: «Зачем ты здесь?». Твой честный ответ (даже самому себе) стабилизирует систему.", "heal", 15),
        RaidContent(160, "Ты находишь «Битый сектор памяти Сатоши Накамото». Внутри — обрывки мыслей о свободе и коде. Ты забираешь этот артефакт.", "loot", 180),
        RaidContent(161, "Глитч-ловушка: «Бесконечная лестница Эшера». Ты бежишь вверх, но остаешься на месте. Твой сигнал падает от когнитивного диссонанса.", "trap", 45),
        RaidContent(162, "Ты встречаешь «Проекцию Стива Джобса». Он критикует твой интерфейс за излишества и удаляет «мусорные» процессы в твоей голове.", "heal", 30),
        RaidContent(163, "Впереди висит «Черная дыра данных». Она затягивает в себя всё вокруг. Тебе приходится использовать весь свой XP, чтобы не быть удаленным.", "trap", 60),
        RaidContent(164, "Ты находишь «Святилище Стрика». Если твой путь был честным, система выдает тебе огромный бонус за верность протоколу.", "loot", 220),
        RaidContent(165, "Труп бота-коллектора. В его руках — долговая расписка твоего конкурента. Информация — это валюта, и ты её забираешь.", "loot", 90),
        RaidContent(166, "Ты попадаешь в «Зеркальную комнату эго». Ты видишь сотни своих версий, которые не справились. Ужас перед неудачей бьет по сигналу.", "trap", 40),
        RaidContent(167, "Ты находишь старый жесткий диск с надписью «База NPC». Ты понимаешь, что 90% мира — это скрипты. Это знание делает тебя Архитектором.", "lore", 0),
        RaidContent(168, "Встреча с «Цифровым Диогеном». Он живет в оцифрованной бочке и ищет «Честного Архитектора». Твоя искренность восстанавливает твой дух.", "heal", 25),
        RaidContent(169, "Ты находишь «Ключ от всех дверей». Он одноразовый, но дает тебе почувствовать абсолютную власть над системой в моменте.", "loot", 110),
        RaidContent(170, "Внезапная инверсия цветов. Твое зрение становится негативом. Ты идешь наощупь, натыкаясь на острые углы битого кода.", "trap", 25),
        RaidContent(171, "Ты находишь «Архив невыполненных обещаний». Читать его больно, но это дает тебе мощный стимул действовать прямо сейчас.", "heal", 15),
        RaidContent(172, "Впереди стоит «Золотой Терминал». Он предлагает сделку: твой самый длинный стрик в обмен на Clearance Level 6. Ты отказываешься, получая уважение системы.", "loot", 150),
        RaidContent(173, "Ты наступаешь на «Цифровую лужу». Это концентрированная меланхолия. Твои мысли становятся тяжелыми, а движения — медленными.", "trap", 20),
        RaidContent(174, "Ты встречаешь бота, который бесконечно пересчитывает число Пи. Ты замечаешь ошибку в его расчетах, и он взрывается, оставляя гору опыта.", "loot", 130),
        RaidContent(175, "Ты выходишь на «Площадь Забытых Логотипов». Здесь покоятся бренды, которые не смогли адаптироваться. Урок выживания усвоен.", "heal", 10),
        RaidContent(176, "Ты находишь старую детскую обувь, оцифрованную с пугающей точностью. Из динамиков доносится смех.", "loot", 45),
        RaidContent(177, "Перед тобой зеркало, но в нем не твое отражение. Там старик грозит тебе пальцем.", "trap", 25),
