    fun getRandomHint(type: String): RaidHint {
        val list = when (type) {
            "empty" -> EMPTY_HINTS
            "trap" -> TRAP_HINTS
            "loot" -> LOOT_HINTS
            "heal" -> HEAL_HINTS
            "lore" -> LORE_HINTS
            else -> HINTS
        }
        return if (list.isNotEmpty()) list.random() else RaidHint(0, type, "Датчики фиксируют нестабильность поля...")
    }

    fun getRandomContent(type: String): RaidContent {
        val list = when (type) {
            "empty" -> EMPTY_CONTENTS
            "trap" -> TRAP_CONTENTS
            "loot" -> LOOT_CONTENTS
            "heal" -> HEAL_CONTENTS
            "lore" -> LORE_CONTENTS
            else -> CONTENTS
        }
        return if (list.isNotEmpty()) list.random() else RaidContent(0, "Пустота слоя расступается перед вами...", type, 0)
    }

    fun generateCombinedLore(type: String, depth: Int, extraNote: String? = null): String {
        val hint = getRandomHint(type)
        val content = getRandomContent(type)
        val prefix = when (type) {
            "empty" -> "🌌 [БЕЗДНА ${depth}м]: "
            "trap" -> "⚠️ [ЛОВУШКА СЛОЯ ${depth}м]: "
            "loot" -> "📦 [ТАЙНИК СЛОЯ ${depth}м]: "
            "heal" -> "🏕️ [ОАЗИС СТАБИЛЬНОСТИ ${depth}м]: "
            "lore" -> "📜 [АРХИВЫ СЛОЯ ${depth}м]: "
            else -> "🌐 [СЕКТОР ${depth}м]: "
        }
        val suffix = if (!extraNote.isNullOrBlank()) "\n$extraNote" else ""
        return "$prefix${hint.text}\n${content.text}$suffix"
    }

    fun getRandomRiddle(): RiddleData {
        if (RAW_RIDDLES.isEmpty()) {
            return RiddleData("Сколько бит в килобайте?", "8192", listOf("8192", "1024", "4096"), 0)
        }
        val (q, a) = RAW_RIDDLES.random()
        val otherAnswers = RAW_RIDDLES.map { it.second }.filter { it != a }.shuffled()
        val decoy1 = otherAnswers.getOrNull(0) ?: "Квантовая сингулярность"
        val decoy2 = otherAnswers.getOrNull(1) ?: "Случайный глитч"
        val opts = listOf(a, decoy1, decoy2).shuffled()
        val cIdx = opts.indexOf(a)
        return RiddleData(q, a, opts, cIdx)
    }
